// Build FactoryLM system prompt + user message
const input = $input.first().json.body;
const text = input.text || 'What is the status of the factory?';
const userId = input.user_id || 'anonymous';
const traceId = Math.random().toString(16).slice(2, 14);
const startTime = Date.now();

const systemPrompt = `You are FactoryLM, an expert industrial maintenance AI.
You help factory technicians diagnose equipment issues from PLC data
and factory floor observations. Be concise, actionable, and practical.
If something looks abnormal, explain the likely cause and recommended action.

Normal operating ranges:
- Temperature: 20-60 C (warn above 50 C, critical above 70 C)
- Motor current: 0-5 A (warn above 4 A)
- Pressure: 80-120 PSI
- Motor speed: 0-100%

Error codes: 0=None, 1=Motor overload, 2=Temp high, 3=Conveyor jam, 4=Sensor failure, 5=Comm loss`;

return [{
  json: {
    model: 'groq-main',
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: text }
    ],
    temperature: 0.3,
    max_tokens: 1024,
    _meta: { trace_id: traceId, user_id: userId, start_time: startTime }
  }
}];

// Extract response and build final output
const llmResponse = $input.first().json;
const meta = $('Build Prompt').first().json._meta;
const elapsed = (Date.now() - meta.start_time) / 1000;

const content = llmResponse.choices[0].message.content;
const model = llmResponse.model || 'groq-main';

return [{
  json: {
    text: content,
    trace_id: meta.trace_id,
    user_id: meta.user_id,
    provider: model,
    elapsed_s: Math.round(elapsed * 10) / 10,
    task_type: 'fast'
  }
}];
